mapper.select:
SELECT a.id, v.id AS vehicle_id, v.vin, COALESCE(a.stage_status, v.lifecycle_stage) AS stage_status, v.lifecycle_stage, p.model_id, m.model_name, m.series, m.spec, m.model_code, p.year_make, p.exterior_color_id, ec.color_name AS exterior_color_name, p.interior_color_id, ic.color_name AS interior_color_name, a.allocated_date, a.dealer_id, d.dealer_name, a.sales_status, a.remark3, a.confirmed_by, a.confirmed_at FROM t_vehicle v LEFT JOIN t_veh_allocation a ON a.vehicle_id = v.id AND a.deleted = 0 LEFT JOIN t_veh_production p ON p.vehicle_id = v.id AND p.deleted = 0 LEFT JOIN t_md_model m ON m.id = p.model_id AND m.deleted = 0 LEFT JOIN t_md_exterior_color ec ON ec.id = p.exterior_color_id AND ec.deleted = 0 LEFT JOIN t_md_interior_color ic ON ic.id = p.interior_color_id AND ic.deleted = 0 LEFT JOIN t_md_dealer d ON d.id = a.dealer_id AND d.deleted = 0 WHERE v.deleted = 0 AND v.lifecycle_stage = 'PENDING_ALLOCATION'
AND v.vin LIKE CONCAT('%', #{query.vin}, '%')
AND a.dealer_id = #{query.dealerId}
AND a.stage_status = #{query.stageStatus}
AND 1 = 0
ORDER BY v.id DESC
